contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs: the hash to lock in, and two amounts: one to fund c's constructor (must have been funded when c deployed),
    // and amount to send to lockInGuess (must be exactly 1 ether for success). We also take a blockNumberDelta to attempt to wait.
    // However, we cannot actually advance blocks here; instead we will assert a relation that holds for any timing: if lockInGuess
    // succeeds and then settle succeeds (does not revert), then either this contract's balance increased by 2 ether or c's balance decreased by 2 ether accordingly.

    // Note: the checker will run this once; msg.sender for calls on c is this contract.

    function run(bytes32 guessHash, uint lockValue, uint extra) public payable {
        require(address(this).balance >= lockValue);
        // Precondition: lockValue must be exactly 1 ether to be accepted by lockInGuess. If not, lockInGuess will revert.
        // We still allow any extra value in case test harness sends some ETH to this contract.

        // Record balances before any interactions
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // Try to lock in a guess with the provided value. Capture whether it reverted.
        bool lockedReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Read the stored guess.block for this contract via the public getter for guesses (auto-generated):
        // The struct getter signature is guesses(address) returns (uint block, bytes32 guess)
        (uint storedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Now try to call settle and record whether it reverted.
        bool settledReverted;
        try c.settle() {
            settledReverted = false;
        } catch {
            settledReverted = true;
        }

        // Balances after
        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;

        // General invariant to assert:
        // If lockInGuess reverted then no state change should have occurred: balances unchanged, storedBlock == 0.
        // Otherwise (lockInGuess succeeded): storedBlock should be non-zero, and if settle succeeded and payed out then this contract's balance increased by 2 ether and c's decreased by 2 ether; if settle succeeded but did not pay out then balances unchanged by 2 ether; if settle reverted then balances reflect only prior effects.
        // We express a concise general rule that covers these cases:

        // - If lockInGuess reverted, then storedBlock == 0 and balances unchanged.
        // - If lockInGuess succeeded and settle succeeded and this contract gained 2 ether, then c lost 2 ether.
        // - If lockInGuess succeeded and settle succeeded and this contract did NOT gain 2 ether, then c did not lose 2 ether.

        assert(
            (lockedReverted && storedBlock == 0 && beforeThis == afterThis && beforeC == afterC)
            ||
            (!lockedReverted && (
                // settle paid out condition
                (!settledReverted && afterThis == beforeThis + 2 ether && afterC + 2 ether == beforeC)
                // settle succeeded but no payout
                || (!settledReverted && !(afterThis == beforeThis + 2 ether) && !(afterC + 2 ether == beforeC) && afterThis == beforeThis && afterC == beforeC)
                // settle reverted or other interleavings: at minimum, storedBlock must have been set when lock succeeded
                || (settledReverted && storedBlock != 0)
            ))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take the guess hash and an amount to send to lockInGuess. The test contract must hold at least that amount.
    // We cannot read internal mapping directly; we infer stored state via whether settle reverts and via balances.
    function run(bytes32 guessHash, uint lockValue) public payable {
        require(address(this).balance >= lockValue);

        // record balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // attempt to call lockInGuess with provided value
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // attempt to call settle; if there was no stored guess for this contract this should revert per contract logic
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // balances after
        uint afterThis = address(this).balance;
        uint afterC = address(c).balance;

        // Assert a general invariant covering both cases:
        // - If lockInGuess reverted then there must be no balance change at all (no Ether moved) and settle must have reverted (no guess set),
        // - Otherwise (lock succeeded): then either settle reverted (still a stored guess exists and settle wasn't allowed to run) or if settle succeeded and this contract gained exactly 2 ether then c's balance decreased by exactly 2 ether; if settle succeeded but this contract did not gain 2 ether then c's balance did not decrease by 2 ether.
        assert(
            // Case A: lock reverted -> no balance changes and settle reverted (since nothing was set)
            (lockReverted && beforeThis == afterThis && beforeC == afterC && settleReverted)
            ||
            // Case B: lock succeeded -> some stored guess existed. Two subcases:
            (!lockReverted && (
                // B1: settle succeeded and paid out 2 ether -> this gained 2 and c lost 2
                (!settleReverted && afterThis == beforeThis + 2 ether && afterC + 2 ether == beforeC)
                // B2: settle succeeded but no payout -> balances unchanged with respect to 2 ether move
                || (!settleReverted && !(afterThis == beforeThis + 2 ether) && !(afterC + 2 ether == beforeC) && beforeThis == afterThis && beforeC == afterC)
                // B3: settle reverted -> stored guess likely still present, so we accept settleReverted
                || (settleReverted)
            ))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: guess hash to lock, amount to send to lockInGuess (must be 1 ether to succeed),
    // and an extra dummy boolean to allow exploration of different call sequences.
    function run(bytes32 guessHash, uint lockValue, bool callSettleBefore) public payable {
        // We need enough balance to call lockInGuess with lockValue and possibly receive payments.
        require(address(this).balance >= lockValue);
        // Record contract C balance before any interactions
        uint beforeC = address(c).balance;

        // Optionally try settle first to observe behavior when no guess is set; we allow it to revert.
        bool settleRevertedBefore;
        try c.settle() {
            settleRevertedBefore = false;
        } catch {
            settleRevertedBefore = true;
        }

        // Attempt to lock in a guess; this may revert (e.g., wrong value or already set), capture that.
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After lock attempt, record intermediate balance
        uint midC = address(c).balance;

        // Attempt to call settle afterwards; it may revert depending on block number or stored state.
        bool settleRevertedAfter;
        try c.settle() {
            settleRevertedAfter = false;
        } catch {
            settleRevertedAfter = true;
        }

        // Final observed balance
        uint afterC = address(c).balance;

        // General rule asserted:
        // If lockInGuess succeeded then final balance of c is either unchanged or decreased by exactly 2 ether (payout).
        // If lockInGuess reverted then c's balance did not increase as a result of this transaction (no unexpected gain).
        assert(
            (
                // Case A: lock failed -> c.balance never increased relative to beforeC
                lockReverted && afterC <= beforeC
            )
            ||
            (
                // Case B: lock succeeded -> c.balance is either same or decreased by 2 ether
                !lockReverted && (
                    afterC == midC || // no payout happened during settle (or settle reverted)
                    (beforeC >= 2 ether && afterC + 2 ether == beforeC) // paid out exactly 2 ether
                )
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes a guess hash and an amount to send when locking (must be 1 ether to succeed).
    // It must also be payable so the test contract can fund the lockInGuess call.
    function run(bytes32 guessHash, uint256 lockAmount) public payable {
        require(address(this).balance >= lockAmount);
        // Precondition: only consider attempts that send exactly 1 ether to match contract requirement
        // but we still model other inputs: if not 1 ether, lockInGuess should revert and leave mapping unchanged (block == 0).

        // Read initial stored block for this test contract's address (invoking auto getter of public mapping `guesses` requires the struct fields accessible via generated getter; since struct is not public, use only settle/lockInGuess effects observable via settle behavior and address balances.)
        // However, C exposes guesses mapping as public? In provided contract it's declared `mapping(address => Guess) guesses;` (not public), so no getter exists. We must instead observe by trying actions and using revert behavior and balances.
        // We'll proceed by: attempt lockInGuess with given amount; capture whether it reverted. Then attempt settle and capture whether it reverts. Finally assert that after these operations, calling lockInGuess again with correct 1 ether will only succeed if previous settle cleared state (i.e., previous guess.block == 0). To observe that, we try lockInGuess again and see if it reverts when sending 1 ether.

        bool firstReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Now call settle; this may revert depending on stored state and block number. Capture revert flag.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Finally attempt to lock again with exactly 1 ether to check whether stored block was cleared.
        // Ensure enough balance available for this call.
        require(address(this).balance >= 1 ether);
        bool secondReverted;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule asserted: if the first lockInGuess succeeded (it accepted exactly 1 ether and set a future block),
        // then after calling settle once (regardless of whether settle itself reverted), it must be possible to call lockInGuess again with 1 ether
        // (i.e., secondReverted == false). Conversely, if the first lockInGuess reverted, then the second attempt should behave the same as the first (revert), so secondReverted equals firstReverted.
        // Combine into a single assertion covering both cases.
        assert((!firstReverted && !secondReverted) || (firstReverted && secondReverted));
    }

    // allow receiving Ether so this contract can fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: a guess hash and exactly 1 ether must be provided by the caller to fund the test contract
    function run(bytes32 guessHash) public payable {
        // require the test contract has at least 1 ether to send to lockInGuess
        require(address(this).balance >= 1 ether);

        // Try to lock in the guess by sending exactly 1 ether. Capture whether it reverted.
        bool lockReverted;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Try to call settle immediately after lockInGuess in the same transaction and capture whether it reverted.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General invariant: If lockInGuess succeeded (did not revert), then an immediate settle() call
        // in the same tx must revert (because settle requires block.number > stored block, and lockInGuess sets a future block).
        // If lockInGuess reverted, we make no claim about settle's behavior, so assert only the implication.
        assert(!lockReverted => settleReverted);
    }

    // allow receiving Ether so this contract can fund calls
    receive() external payable {}
}
